isprime = [True] * (n + 1)
for i in range(2, n + 1):
    if isprime[i]:
        for j in range(i + i, n, i):
            isprime[j] = False
for i in range(n - 1, 0, -1):
    if isprime[i] and n % i == 0:
        return i

